WITH max_concurrency AS (
  SELECT MAX(concurrent_users) AS peak_concurrent
  FROM ads_platform_concurrency
)
SELECT peak_concurrent
FROM max_concurrency;

SELECT n_viewers
FROM dws_streamer_day
WHERE streamer = 'ninja' AND day_index = 10;

SELECT COUNT(*) as user_count
FROM dim_user
WHERE n_streamers_watched > 50;
